@partitioned_dag_runs_router.get(
    "/partitioned_dag_runs",
    dependencies=[Depends(requires_access_asset(method="GET"))],
)
def get_partitioned_dag_runs(
    session: SessionDep,
    readable_dags_filter: ReadableDagsFilterDep,
    dag_id: QueryPartitionedDagRunDagIdFilter,
    has_created_dag_run_id: QueryPartitionedDagRunHasCreatedDagRunIdFilter,
) -> PartitionedDagRunCollectionResponse:
    if dag_id.value is not None:
        dag_info = session.execute(
            select(
                DagModel.timetable_summary,
                func.count(DagScheduleAssetReference.asset_id).label("required_count"),
            )
            .outerjoin(...)
            .where(DagModel.dag_id == dag_id.value)
            .group_by(DagModel.dag_id)
        ).one_or_none()
        if dag_info is None:
            raise HTTPException(status.HTTP_404_NOT_FOUND, f"Dag with id {dag_id.value} was not found")
        if dag_info.timetable_summary != "Partitioned Asset":
            return PartitionedDagRunCollectionResponse(partitioned_dag_runs=[], total=0)
        required_count = dag_info.required_count

readable_dag_ids = readable_dags_filter.value
if readable_dag_ids is not None:
    query = query.where(AssetPartitionDagRun.target_dag_id.in_(readable_dag_ids))

def requires_access_dag(
    method: ResourceMethod,
    access_entity: DagAccessEntity | None = None,
    param_dag_id: str | None = None,
) -> Callable[[Request, BaseUser], None]:
    def inner(request: Request, user: GetUserDep) -> None:
        dag_id = param_dag_id
        if dag_id is None:
            dag_id = request.path_params.get("dag_id") or request.query_params.get("dag_id")
            dag_id = dag_id if dag_id != "~" else None
        team_name = DagModel.get_team_name(dag_id) if dag_id else None
        _requires_access(
            is_authorized_callback=lambda: get_auth_manager().is_authorized_dag(
                method=method,
                access_entity=access_entity,
                details=DagDetails(id=dag_id, team_name=team_name),
                user=user,
            )
        )
    return inner

